package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class MatchEventService { private final MatchEventRepository events; private final MatchRepository matches; private final PlayerRepository players; public MatchEventService(MatchEventRepository events, MatchRepository matches, PlayerRepository players){this.events=events;this.matches=matches;this.players=players;} @Transactional public MatchEvent addEvent(Long matchId, Long playerId, MatchEvent event){event.setMatch(matches.findById(matchId).orElseThrow()); event.setPlayer(players.findById(playerId).orElseThrow()); return events.save(event);} @Transactional public void bulkImportEvents(Long matchId){ } public List<MatchEvent> getMatchTimeline(Long matchId){return events.findByMatch_IdOrderByMinuteAscSecondAsc(matchId);} }
